<template>
  <div>
    <el-form
      :model="ruleForm"
      :rules="rules"
      ref="ruleForm"
      label-width="130px"
      class="demo-ruleForm mt-30"
      size="small"
    >
      <el-form-item label="IP地址或者域名:" prop="tool_url">
        <el-input v-model="ruleForm.tool_url" style="width: 30%" />
      </el-form-item>
      <el-form-item label="检测结果:" prop="save_duration">
        <el-input
          type="textarea"
          v-model="ruleForm.tool_info"
          :autosize="{ minRows: 6, maxRows: 18 }"
          style="width: 80%"
          readonly
        />
      </el-form-item>
      <el-form-item>
        <el-button
          v-if="!isTask"
          type="primary"
          @click="submitForm('ruleForm')"
          :loading="loading"
        >
          开始检测
        </el-button>
        <el-button v-else type="danger" @click="stopTask">停止检测</el-button>
      </el-form-item>
    </el-form>
  </div>
</template>

<script>
export default {
  data() {
    let validateIP = (rule, value, callback) => {
      const ipv4Regex =
        /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
      const domainRegex = /^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$/;
      if (!ipv4Regex.test(value) && !domainRegex.test(value)) {
        callback(new Error("IP地址或者域名格式输入不正确"));
      } else {
        callback();
      }
    };
    return {
      ruleForm: {
        tool_url: "",
        tool_info: "",
      },
      rules: {
        tool_url: [
          {
            required: true,
            message: "请输入IP或域名",
            trigger: ["blur", "change"],
          },
          { validator: validateIP, trigger: ["blur", "change"] },
        ],
      },
      isTask: false,
      loading: false,
      timer: null,
      tool_tag: 1,
    };
  },
  methods: {
    async getPing() {
      try {
        const res = await this.$api.get("/sys/getPing");
        let data = res.data.data;
        if (data) {
          this.$set(this.ruleForm, "tool_info", data.tool_info);
          this.tool_tag = data.tool_tag;
        }
        return true;
      } catch (error) {
        console.error("获取检测结果失败:", error);
        return false;
      }
    },

    async startPolling() {
      console.log(this.tool_tag);
      const poll = async () => {
        this.isTask = this.tool_tag == 1 ? true : false;
        if (!this.isTask) return;
        const success = await this.getPing();
        if (success && this.isTask) {
          this.timer = setTimeout(poll, 1000);
        }
      };

      await poll();
    },

    async submitForm(formName) {
      this.ruleForm.tool_info = "";
      this.tool_tag = 1;
      try {
        const valid = await this.$refs[formName].validate();
        if (!valid) return;

        this.loading = true;
        await this.$api.post("/sys/startPing", {
          tool_url: this.ruleForm.tool_url,
        });
        await this.startPolling();
      } catch (error) {
        console.error("启动检测失败:", error);
      } finally {
        this.loading = false;
      }
    },

    async stopTask() {
      try {
        await this.$api.post("/sys/stopPing");
        this.isTask = false;
        clearTimeout(this.timer);
        this.timer = null;
      } catch (error) {
        console.error("停止检测失败:", error);
      }
    },
  },

  beforeDestroy() {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
  },
};
</script>

<style scoped>
.mt-30 {
  margin-top: 30px;
}
</style>
